const D = { energy: .6, scale: 1, speed: 1, density: .5, spacing: .5, grain: .45, hue: 28, x: .5, y: .5, style: 'gel', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Liesegang rings -- periodic precipitation by the Ostwald supersaturation cycle.
// An outer electrolyte B invades a gel loaded with A. They react into a soluble
// product; where the product passes the NUCLEATION threshold it precipitates,
// which locally strips the product back down, so the front must run on and
// re-supersaturate before it can band again. Result: discrete rings with
// widening spacing, not a smooth gradient. Product below the nucleation
// threshold but above the (lower) GROWTH threshold feeds existing bands instead
// of starting new ones -- that asymmetry is what makes the banding sharp.
//
// A single source dies: the front reaches the wall and the plate is finished
// (STATIC). Kept perpetual by three coupled mechanisms:
//   (1) fresh sources keep being pipetted in at a floored rate, so new ring
//       systems are always invading and colliding with old ones;
//   (2) the gel slowly recharges with A behind the fronts;
//   (3) laid-down precipitate slowly redissolves and ripens away, so the medium
//       is continuously wiped clean and can band again.
// ---------------------------------------------------------------------------
const BW = 160, BH = Math.max(80, Math.round(BW * height / width));
const N = BW * BH;
const MAXS = 8;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.a = new Float32Array(N); S.b = new Float32Array(N); S.c = new Float32Array(N);
  S.p = new Float32Array(N); S.lp = new Float32Array(N); S.age = new Float32Array(N);
  S.sx = new Float32Array(MAXS); S.sy = new Float32Array(MAXS);
  S.ss = new Float32Array(MAXS); S.sh = new Float32Array(MAXS);
  S.init = false; S.seedUsed = null;
}

const sd = P.seed | 0;
function hs3(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
let RR = 0, GG = 0, BB = 0;
function hsv(h, s, v) {
  h = h - Math.floor(h);
  const i = Math.floor(h * 6), f = h * 6 - i, p2 = v * (1 - s), q = v * (1 - f * s), w = v * (1 - (1 - f) * s);
  if (i === 0) { RR = v; GG = w; BB = p2; } else if (i === 1) { RR = q; GG = v; BB = p2; }
  else if (i === 2) { RR = p2; GG = v; BB = w; } else if (i === 3) { RR = p2; GG = q; BB = v; }
  else if (i === 4) { RR = w; GG = p2; BB = v; } else { RR = v; GG = p2; BB = q; }
}
function rnd() { let x = S.rng; x ^= x << 13; x |= 0; x ^= x >>> 17; x ^= x << 5; x |= 0; S.rng = x; return (x >>> 0) / 4294967296; }

const af = S.a, bf = S.b, cf = S.c, pf = S.p, lp = S.lp, age = S.age;
const sxs = S.sx, sys = S.sy, sss = S.ss, shs = S.sh;

if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  S.rng = (sd * 2654435761 + 0x9e3779b9) | 0; if (S.rng === 0) S.rng = 1;
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
    const p = j * BW + i;
    af[p] = 0.92 + (hs3(i, j, 3) - 0.5) * 0.08;   // gel loaded with A
    bf[p] = 0; cf[p] = 0; pf[p] = 0; age[p] = 0;
  }
  S.ns = 2;
  for (let k = 0; k < 2; k++) {
    sxs[k] = (0.25 + rnd() * 0.5) * BW; sys[k] = (0.25 + rnd() * 0.5) * BH;
    sss[k] = 1; shs[k] = rnd();
  }
  S.nacc = 0;
}

const tt = K.t;
function lap(src, dst) {
  for (let j = 0; j < BH; j++) {
    const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
      dst[jc + i] = src[jm + i] + src[jp + i] + src[jc + im] + src[jc + ip] - 4 * src[jc + i];
    }
  }
}

// ---- sources: fresh reagent keeps being pipetted in (floored rate) ----
let ns = S.ns;
const srate = 0.075 + P.density * 0.36;            // sources per second
S.nacc += srate / 60;
while (S.nacc >= 1) {
  S.nacc -= 1;
  if (ns < MAXS) {
    sxs[ns] = (0.08 + rnd() * 0.84) * BW; sys[ns] = (0.08 + rnd() * 0.84) * BH;
    sss[ns] = 1; shs[ns] = rnd(); ns++;
  } else {                                          // recycle the most spent source
    let worst = 0;
    for (let k = 1; k < MAXS; k++) if (sss[k] < sss[worst]) worst = k;
    sxs[worst] = (0.08 + rnd() * 0.84) * BW; sys[worst] = (0.08 + rnd() * 0.84) * BH;
    sss[worst] = 1; shs[worst] = rnd();
  }
}
S.ns = ns;

const steps = Math.max(1, Math.min(5, Math.round(1.5 + P.speed * 2.2)));
const Da = 0.15, Db = 0.23;
const ka = 0.052 + P.speed * 0.015;
const Kn = 0.018 + P.spacing * 0.055;               // nucleation threshold -> band spacing
const Kg = Kn * 0.32;                               // growth threshold (must be < Kn)
const refill = 0.00012 * (0.4 + P.density * 1.2);   // gel recharges with A over ~50s
const diss = 0.00019 * (0.4 + (1 - P.spacing) * 0.8); // bands ripen away over ~35s
const inj = 0.85 + P.density * 0.35;

for (let st = 0; st < steps; st++) {
  // inject B at every live source; sources deplete and drift
  for (let k = 0; k < ns; k++) {
    if (sss[k] <= 0.001) continue;
    const ix = sxs[k] | 0, iy = sys[k] | 0;
    for (let dj = -1; dj <= 1; dj++) for (let di = -1; di <= 1; di++) {
      const ii = ix + di, jj = iy + dj;
      if (ii < 0 || ii >= BW || jj < 0 || jj >= BH) continue;
      const q = jj * BW + ii;
      const held = inj * sss[k];
      if (bf[q] < held) bf[q] = held;      // reservoir held at b0, not an injection
    }
    sss[k] -= 0.00022 * (0.5 + P.speed * 0.8);
    if (sss[k] < 0) sss[k] = 0;
  }
  // diffusion
  lap(af, lp); for (let p = 0; p < N; p++) af[p] += Da * lp[p];
  lap(bf, lp); for (let p = 0; p < N; p++) bf[p] += Db * lp[p];
  // reaction A + B -> product, then the Ostwald nucleation / growth rule
  for (let j = 0; j < BH; j++) {
    const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const p = jc + i;
      const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
      let a2 = af[p], b2 = bf[p];
      const r = ka * a2 * b2;
      a2 -= r; b2 -= r;
      let pp = pf[p] + r;
      const cc = cf[p];
      // does an existing band touch this cell?
      const nb = cc > 0.004 || cf[jc + im] > 0.004 || cf[jc + ip] > 0.004 || cf[jm + i] > 0.004 || cf[jp + i] > 0.004;
      let nc = cc;
      if (pp > Kn) { nc += pp * 0.92; pp *= 0.08; if (age[p] === 0) age[p] = 0.05 + (tt * 0.031) % 1; }
      else if (nb && pp > Kg) { nc += (pp - Kg) * 0.75; pp -= (pp - Kg) * 0.75; }
      // recharge the gel, ripen the bands away
      a2 += (0.95 - a2) * refill;
      nc -= nc * diss;
      if (nc < 0.0015) { nc = 0; age[p] = 0; }
      af[p] = a2 < 0 ? 0 : a2; bf[p] = b2 < 0 ? 0 : b2;
      pf[p] = pp < 0 ? 0 : pp; cf[p] = nc > 1.6 ? 1.6 : nc;
    }
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const style = P.style;
const hb = P.hue / 360 + (K.section | 0) * 0.021 + Math.sin(tt * 0.015) * 0.018;
const gain = 0.45 + P.energy * 1.15 + A.rms * 0.35;
const gr = P.grain;
for (let j = 0; j < BH; j++) {
  const jc = j * BW;
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW;
  for (let i = 0; i < BW; i++) {
    const p = jc + i;
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    const c2 = Math.min(1, cf[p] * 1.25);
    const b2 = Math.min(1, bf[p] * 2.6);
    const a2 = Math.min(1, af[p]);
    const th = (hs3(i, j, 61) - 0.5) * 0.09 * gr;
    let r, gg, b;
    if (style === 'agate') {
      // banded chalcedony: each band takes a mineral colour from when it was laid
      const ag = age[p];
      hsv(hb + ag * 0.52 + c2 * 0.06, 0.30 + 0.34 * Math.sin(ag * 19.7 + 1.1), 1);
      const dens = Math.pow(c2, 0.72);
      const host = 0.20 + a2 * 0.10 + b2 * 0.05;
      const lit = dens * (0.42 + gain * 0.52);
      r = host * 0.95 + RR * lit; gg = host * 0.92 + GG * lit; b = host * 1.05 + BB * lit;
    } else if (style === 'darkfield') {
      // scattering rings glowing out of a black bath
      hsv(hb + 0.03, 0.42, 1);
      const lit = Math.pow(c2, 0.85) * (0.55 + gain * 0.7);
      r = 0.035 + RR * lit + b2 * 0.05; gg = 0.045 + GG * lit + b2 * 0.08; b = 0.085 + BB * lit + b2 * 0.14;
    } else if (style === 'schematic') {
      // blueprint: band contours and the invading front, nothing else
      const gx = Math.min(1, cf[jc + ip]) - Math.min(1, cf[jc + im]);
      const gy = Math.min(1, cf[jp + i]) - Math.min(1, cf[jm + i]);
      const edge = Math.min(1, Math.sqrt(gx * gx + gy * gy) * 3.4);
      const base = 0.065 + a2 * 0.025;
      r = base * 0.5 + edge * 0.45 * gain + b2 * 0.10;
      gg = base * 0.9 + edge * 0.85 * gain + b2 * 0.20;
      b = base * 1.85 + edge * 1.0 * gain + b2 * 0.30;
    } else {
      // gel (default): silver-dichromate ochre bands suspended in a translucent
      // green-grey gel, the invading front still visible as a diffusion halo
      hsv(hb, 0.62 - c2 * 0.14, 1);
      const dens = Math.pow(c2, 0.8);
      const gelv = 0.30 + a2 * 0.16;
      hsv(hb + 0.36, 0.26, 1);
      const gr2 = RR, gg2 = GG, gb2 = BB;
      hsv(hb, 0.62 - c2 * 0.14, 1);
      const lit = dens * (0.44 + gain * 0.55);
      r = gr2 * gelv + RR * lit + b2 * 0.045;
      gg = gg2 * gelv + GG * lit + b2 * 0.075;
      b = gb2 * gelv + BB * lit + b2 * 0.05;
    }
    const o = 4 * p;
    px[o] = Math.max(0, Math.min(255, (r + th) * 255));
    px[o + 1] = Math.max(0, Math.min(255, (gg + th) * 255));
    px[o + 2] = Math.max(0, Math.min(255, (b + th) * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh2 = BH / z;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh2) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh2);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
